def convert_to_ascii(strings):
    # Create an empty dictionary to store the results
    result = {}

    # Loop through each string in the input list
    for string in strings:
        # Get the ASCII value of each character in the string
        ascii_values = [ord(char) for char in string]

        # Add the original string and its ASCII values to the result dictionary
        result[string] = ascii_values

    # Return the JSON object containing the results
    return json.dumps(result)
