import json

class JSONObjectParser:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_func):
        self.registry[id] = factory_func

    def create_from_json(self, json_str):
        data = json.loads(json_str)
        return self.create_instance(data)

    def create_instance(self, data):
        if 'id' not in data:
            raise ValueError(""JSON data missing 'id' field"")

        id = data['id']
        if id not in self.registry:
            raise ValueError(f""No factory registered for ID: {id}"")

        return self.registry[id](data)

class JSONObjectFactory:
    @staticmethod
    def create_custom_object(data):
        # Implement custom object creation logic here
        pass

# Example usage
parser = JSONObjectParser()
parser.add_factory('custom', JSONObjectFactory.create_custom_object)
json_str = '{""id"": ""custom"", ""data"": ""example""}'
obj = parser.create_from_json(json_str)
```
