def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_primes(my_list):
    prime_sum = 0
    for num in my_list:
        if isinstance(num, int) and is_prime(num):
            prime_sum += num
    return prime_sum
