0,"Develop a command-line utility that accepts a file as input and calculates the total number of unique words present in the file. The utility should ignore case sensitivity and consider punctuation as part of words. It should also provide an option to output the result to a specified file or display it on the console. If no output file is specified, the result should be printed to the console. The program should accept multiple input files and aggregate their unique word counts.",121,,"[""```
import re
from collections import Counter

class UniqueWordCounter:
    def __init__(self):
        self.word_counts = Counter()

    def add_file(self, file_path):
        with open(file_path) as f:
            for line in f:
                words = re.findall(r'\w+', line.lower())
                self.word_counts.update(words)

    def get_unique_word_count(self, file_path):
        self.add_file(file_path)
        return len(self.word_counts)

    def write_to_file(self, output_file):
        with open(output_file, 'w') as f:
            for word, count in self.word_counts.most_common():
                f.write('{} {}\n'.format(word, count))

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('input_files', nargs='+')
    parser.add_argument('-o', '--output-file', default=None)
    args = parser.parse_args()

    counter = UniqueWordCounter()
    for file in args.input_files:
        counter.add_file(file)

    if args.output_file is not None:
        counter.write_to_file(args.output_file)
    else:
        print(counter.get_unique_word_count())
