def convert_strings_to_ascii(input_list):
    output = {}
    total_length = 0
    total_chars = 0
    avg_ascii = 0
    for string in input_list:
        ascii_values = []
        for char in string:
            ascii_value = ord(char)
            ascii_values.append(ascii_value)
        output[string] = {""ASCII values"": ascii_values, ""length"": len(string), ""total characters"": total_chars + len(string)}
        total_length += len(string)
        total_chars += len(string)
    avg_ascii = total_chars / total_length
    output[""average ASCII value""] = avg_ascii
    return json.dumps(output)
