import hashlib

def compute_file_md5(filepath):
    BUF_SIZE = 65536  # 64 KB
    hash = hashlib.md5()
    with open(filepath, 'rb') as f:
        while True:
            chunk = f.read(BUF_SIZE)
            if not chunk:
                break
            hash.update(chunk)
    return hash.hexdigest()
