// ThemeCacheManager.kt
import android.content.Context
import android.graphics.Bitmap
import android.os.Environment
import android.util.Log

class ThemeCacheManager {
    companion object {
        private const val TAG = ""ThemeCacheManager""

        // Define a directory for storing the theme cache
        fun getThemeCacheDir(context: Context): File {
            return File(Environment.getExternalStorageDirectory(), ""theme_cache"")
        }

        // Check if a theme bitmap is recycled and, if not, recycle it and set it to null
        fun checkAndRecycleBitmap(bitmap: Bitmap) {
            if (bitmap != null && !bitmap.isRecycled()) {
                Log.d(TAG, ""Recycling bitmap: $bitmap"")
                bitmap.recycle()
            }
        }
    }
}
```
```
// ThemeCacheManager.swift
import UIKit
import Foundation

class ThemeCacheManager {
    private static let TAG = ""ThemeCacheManager""

    // Define a directory for storing the theme cache
    class func getThemeCacheDir() -> URL {
        return FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent(""theme_cache"")
    }

    // Check if a theme bitmap is recycled and, if not, recycle it and set it to null
    class func checkAndRecycleBitmap(_ bitmap: UIImage) {
        if let image = bitmap as? UIImage, !image.isRecycled() {
            Log.d(TAG, ""Recycling bitmap: \(bitmap)"")
            image.recycle()
        }
    }
}
