import os
import csv
import json

def process_csv_files(directory_path):
    extracted_values = []
    for filename in os.listdir(directory_path):
        if filename.endswith('.csv'):
            file_path = os.path.join(directory_path, filename)
            process_csv_file(file_path, extracted_values)

    calculate_frequencies(extracted_values)
    convert_to_json(extracted_values)

def process_csv_file(file_path, extracted_values):
    with open(file_path, 'r', newline='', encoding='utf-8') as csvfile:
        csv_reader = csv.reader(csvfile)
        for row in csv_reader:
            for value in row:
                if value and value != 'nan':
                    extracted_values.append(value)

def calculate_frequencies(values):
    frequency_array = [0] * len(values)
    for value in values:
        index = values.index(value)
        frequency_array[index] += 1

    return frequency_array

def convert_to_json(frequency_array):
    frequencies_dict = {}
    for i, freq in enumerate(frequency_array):
        frequencies_dict[values[i]] = freq

    json_output = json.dumps(frequencies_dict)
    print(json_output)

if __name__ == '__main__':
