This system must enable users to view their list of tasks, add new tasks with details (title and description), modify existing tasks' specifics or completely remove them from the database.",290,,"[""```
import sqlalchemy as sa
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
from sqlalchemy import Column, Integer, String, DateTime

Base = declarative_base()

class Task(Base):
    __tablename__ = 'tasks'
    id = Column(Integer, primary_key=True)
    title = Column(String)
    description = Column(String)
    created_at = Column(DateTime)
    updated_at = Column(DateTime)

engine = sa.create_engine('sqlite:///task-management.db')
Session = sessionmaker(bind=engine)
session = Session()

def create_task(title, description):
    task = Task(title=title, description=description)
    try:
        session.add(task)
        session.commit()
        return {'success': True}
    except Exception as e:
        session.rollback()
        return {'success': False, 'error': str(e)}

def update_task(id, title=None, description=None):
    task = session.query(Task).get(id)
    if not task:
        return {'success': False, 'error': f'Task with id {id} not found.'}
    try:
        if title is not None:
            task.title = title
        if description is not None:
            task.description = description
        session.commit()
        return {'success': True}
    except Exception as e:
        session.rollback()
        return {'success': False, 'error': str(e)}

def delete_task(id):
    task = session.query(Task).get(id)
    if not task:
        return {'success': False, 'error': f'Task with id {id} not found.'}
    try:
        session.delete(task)
        session.commit()
        return {'success': True}
    except Exception as e:
        session.rollback()
        return {'success': False, 'error': str(e)}

def get_tasks():
    tasks = session.query(Task).all()
    return [{'id': task.id, 'title': task.title, 'description': task.description, 'created_at': task.created_at, 'updated_at': task.updated_at} for task in tasks]

def get_task(id):
    task = session.query(Task).get(id)
    if not task:
        return {'success': False, 'error': f'Task with id {id} not found.'}
    return {'id': task.id, 'title': task.title, 'description': task.description, 'created_at': task.created_at, 'updated_at': task.updated_at}
```
