        uuid = str(uuid.uuid4())
        operational_status = ""ACTIVE"" if random.randint(0, 1) else ""INACTIVE""
        tags = {}
        for key, value in TAG_KEYS:
            tags[key] = random.choice(TAG_VALUES)
        vm_configs.append(VMAPI_T(uuid, operational_status, tags))
    return vm_configs

def generateUUIDs(n: int, max_size: int) -> List[str]:
    uuids = []
    for _ in range(n):
        while True:
            try:
                uuid = str(uuid.uuid4())
                if len(uuid) <= max_size:
                    uuids.append(uuid)
                    break
            except MemoryError as e:
                disposeResources()
                continue
            else:
                break
    return uuids

def disposeResources():
    pass

def writeToXMLFile(vm_configs: List[VMAPI_T], file_name: str):
    root = etree.Element(""VirtualMachines"")
    for vm_config in vm_configs:
        vm = etree.SubElement(root, ""VirtualMachine"")
        vm.set(""uuid"", vm_config.uuid)
        vm.set(""operationalStatus"", vm_config.operational_status)
        for key, value in vm_config.tags.items():
            tag = etree.SubElement(vm, ""Tag"")
            tag.set(""key"", key)
            tag.set(""value"", value)
    with open(file_name, ""wb"") as f:
        f.write(etree.tostring(root, encoding=""unicode""))

def writeToYAMLFile(vm_configs: List[VMAPI_T], file_name: str):
    with open(file_name, ""w"") as f:
        yaml.dump(vm_configs, f)
