# Utility Program for Counting Unique Characters in Text Files
import os

def main():
    # Get user input for text files to process
    files = get_files()

    # Create dictionary to store unique characters
    char_dict = {}

    # Process each file and add its unique characters to the dictionary
    for file in files:
        with open(file, 'r') as f:
            for line in f:
                for char in line:
                    if char.isalpha() or char.isdigit():
                        char_dict[char] = char_dict.get(char, 0) + 1

    # Output the total count of unique characters to console or file
    output(char_dict)

def get_files():
    files = []
    while True:
        file = input(""Enter a text file path (or press Enter to finish): "")
        if not file:
            break
        files.append(file)
    return files

def output(char_dict):
    total_count = 0
    for char, count in char_dict.items():
        total_count += count
    print(""Total unique characters:"", total_count)

if __name__ == ""__main__"":
    main()
