import os
import argparse
import glob

def parse_arguments():
    parser = argparse.ArgumentParser(description=""Directory analysis tool"")
    parser.add_argument(""directory"", help=""Target directory to analyze"")
    parser.add_argument(""--total"", action=""store_true"", help=""Show total line count"")
    parser.add_argument(""--files"", action=""store_true"", help=""List only the files"")
    parser.add_argument(""--output"", type=str, help=""Save output to a file"")
    return parser.parse_args()

def analyze_directory(directory, total=False, files=False, output=None):
    line_count = 0
    file_list = []

    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.txt'):
                filepath = os.path.join(root, file)
                with open(filepath, 'r', encoding='utf-8') as f:
                    line_count += sum(1 for _ in f)
                    file_list.append(filepath)

    if total:
        print(f""Total lines: {line_count}"")
        return line_count
    elif files:
        print(""\n"".join(file_list))
        return file_list
    else:
        if output:
            with open(output, 'w', encoding='utf-8') as f:
                f.write(""\n"".join(file_list))
            print(f""Output saved to {output}"")
        else:
            print(""\n"".join(file_list))

if __name__ == ""__main__"":
    args = parse_arguments()

    if not args.directory or not os.path.exists(args.directory) or not os.path.isdir(args.directory):
        print(""Invalid directory provided."")
        exit(1)

    try:
        result = analyze_directory(args.directory,
                                   total=args.total,
                                   files=args.files,
                                   output=args.output)

        if result is None and args.total is False and args.files is False and args.output is None:
            raise ValueError(""No output specified and no additional options provided."")

    except Exception as e:
        print(f""Error: {e}"")
